// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Adopt and discard in the editor"
// Changes: Adopt and discard from a session opened on a draft (fake transport): chosen parts reach the project, the
//          draft ends and the view becomes read-only; a stale project refuses with the fresh state; unsaved edits are
//          saved first; discarding ends the draft without touching the project.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { defaultProjectData } from './project'
import { createProjectSession } from './projectSession'
import { createFakeTransport } from './projectTransport.fake'
import type { ProjectRecord } from '#/server/projects.server'

const project = (): ProjectRecord => ({
  id: 'p1',
  name: 'Výrazy',
  data: { ...defaultProjectData(), ll: { grammar: 'E -> id', input: 'id' }, prec: { ...defaultProjectData().prec, rules: 'E -> id' } },
  revision: 3,
  createdAt: '2026-01-01T00:00:00.000Z',
  updatedAt: '2026-01-01T00:00:00.000Z',
  view: { llSim: { step: 0, speed: 1 } },
})

async function openDraft() {
  const fake = createFakeTransport(project())
  const draft = fake.createDraft('Oprava')
  fake.agentEdit(draft.id, { grammarRules: 'E -> a', reductionRules: 'E -> a' })
  const session = createProjectSession((await fake.transport.loadDraft({ draftId: draft.id }))!, fake.transport)
  session.resume()
  return { fake, draft, session, state: () => session.getState() }
}

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

describe('adopting the open draft', () => {
  it('writes the chosen parts into the project and ends the draft; the view becomes read-only', async () => {
    const { fake, draft, session, state } = await openDraft()

    const result = await session.adopt(['grammarRules'], 3)

    expect(result).toMatchObject({ status: 'adopted', project: { revision: 4 } })
    expect(fake.server.record!.data.ll).toEqual({ grammar: 'E -> a', input: 'id' })
    expect(fake.server.record!.data.prec.rules).toBe('E -> id')
    expect(fake.draft(draft.id)!.state).toBe('adopted')
    expect(state()).toMatchObject({ readOnly: true, draft: { state: 'adopted' } })
  })

  it('is refused when the project moved past the revision the human decided on, returning the fresh project', async () => {
    const { fake, draft, session, state } = await openDraft()
    fake.externalSave({ ...project().data, ll: { grammar: 'E -> b', input: 'id' } })

    const result = await session.adopt(['grammarRules'], 3)

    expect(result).toMatchObject({ status: 'stale', project: { revision: 4, data: { ll: { grammar: 'E -> b' } } } })
    expect(fake.draft(draft.id)!.state).toBe('open')
    expect(state()).toMatchObject({ readOnly: false, draft: { state: 'open' } })
    // With the fresh revision the human can adopt.
    expect(await session.adopt(['grammarRules'], 4)).toMatchObject({ status: 'adopted', project: { revision: 5 } })
  })

  it("saves the human's unsaved edits into the draft first, so they are adopted too", async () => {
    const { fake, session } = await openDraft()
    session.edit((d) => ({ ...d, ll: { ...d.ll, grammar: 'E -> human' } }))

    await session.adopt(['grammarRules'], 3)

    expect(fake.server.record!.data.ll.grammar).toBe('E -> human')
  })

  it('a draft that ended elsewhere refuses with the reason and becomes read-only', async () => {
    const { fake, draft, session, state } = await openDraft()
    fake.discardDraft(draft.id)
    await expect(session.adopt(['grammarRules'], 3)).rejects.toThrow(/ukončený/)
    expect(state().readOnly).toBe(true)
    expect(fake.server.record!.revision).toBe(3)
  })
})

describe('discarding the open draft', () => {
  it('ends the draft as discarded; the project is untouched and the view becomes read-only', async () => {
    const { fake, draft, session, state } = await openDraft()

    await session.discard()

    expect(fake.draft(draft.id)).toMatchObject({ state: 'discarded' })
    expect(fake.draftSnapshots(draft.id)).toEqual([expect.objectContaining({ kind: 'final', grammarRules: 'E -> a' })])
    expect(fake.server.record).toMatchObject({ revision: 3, data: project().data })
    expect(state()).toMatchObject({ readOnly: true, draft: { state: 'discarded' } })
  })

  it("keeps the human's unsaved edits in the final snapshot", async () => {
    const { fake, draft, session } = await openDraft()
    session.edit((d) => ({ ...d, ll: { ...d.ll, grammar: 'E -> human' } }))
    await session.discard()
    expect(fake.draftSnapshots(draft.id).at(-1)).toMatchObject({ kind: 'final', grammarRules: 'E -> human' })
  })
})
